  "items": [
    {
      "title": "Destatis GENESIS-Online: Hospital Patients by Main Diagnosis (ICD-10), Germany, 2000–2024",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/23131/table/23131-0001",
      "justification": "Official German Federal Statistical Office dataset containing annual hospital discharge statistics by ICD-10 diagnosis. Covers injuries, poisoning, and other consequences of external causes (ICD-10 S00–T98), including open wounds, fractures, burns, and traumatic injuries. Covers the entire 2010s and 2020–2024, making it particularly suitable for analyzing national trends in injury-related hospitalizations."
    },
    {
      "title": "Destatis GENESIS-Online: Hospital Patients by Diagnosis, Sex, and Age Group",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/23131/details",
      "justification": "Official German hospital diagnosis statistics, including table 23131-0002, which provides annual hospital discharge data by ICD-10 diagnosis, sex, and age group. Researchers can select injury and wound diagnoses within ICD-10 S00–T98 to investigate demographic differences in injuries during the 2010s and 2020s."
    },
    {
      "title": "Destatis GENESIS-Online: Hospital Patients by Federal State, Diagnosis, Sex, and Age",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/23131/table/23131-0011",
      "justification": "Official dataset providing hospital diagnoses across Germany's federal states, differentiated by year, age, sex, and ICD-10 diagnosis. Includes wound and injury categories such as open wounds, fractures, and burns. Useful for identifying regional differences in injury-related hospitalizations and comparing demographic patterns over time."
    },
    {
      "title": "Destatis GENESIS-Online: Road Traffic Accidents with Serious and Minor Injuries",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/46241/details",
      "justification": "Official German road traffic accident statistics. Table 46241-0003 provides annual information on accidents involving personal injury, fatalities, seriously injured persons, and slightly injured persons, classified by road category and location. Particularly useful for studying injury severity and changes in road traffic injuries during the 2010s and 2020s."
    },
    {
      "title": "Destatis: Long-Term Series of Road Traffic Accidents and Injuries in Germany",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Society-Environment/Traffic-Accidents/Tables/liste-traffic-accidents.html",
      "justification": "Official longitudinal statistics reporting annual road traffic accidents, accidents involving personal injury, fatalities, and injured persons in Germany. Includes observations throughout the 2010s and into the 2020s. Suitable for studying long-term trends in traffic-related injuries and evaluating changes before, during, and after the COVID-19 pandemic."
    },
    {
      "title": "Destatis GENESIS-Online: Police-Recorded Road Traffic Accidents, 2008–2025",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/table/46241-0001",
      "justification": "Official annual dataset covering police-recorded traffic accidents in Germany from 2008 to 2025. Distinguishes accidents involving personal injuries from accidents causing property damage and provides geographic classifications by road location. Useful for examining injury-producing accidents over both decades, although it does not provide individual medical diagnoses."
    },
    {
      "title": "Destatis Accident Atlas: Georeferenced Road Traffic Accidents in Germany",
      "url_or_doi": "https://data.europa.eu/data/datasets/f433e6d0-840b-4bfe-bdc9-ba86f4245781?locale=en",
      "justification": "Official open geospatial dataset containing police-recorded road traffic accidents in Germany. Provides accident locations and characteristics and is updated annually. Particularly valuable for geographical analysis of road accidents involving injuries during the late 2010s and 2020s. Individual-level medical information about injured persons is not included."
    },
    {
      "title": "MFDZ: Harmonized Destatis Accident Atlas Data from 2016 Onward",
      "url_or_doi": "https://data.mfdz.de/destatis_Unfalldaten/index.html",
      "justification": "Research-oriented dataset combining and harmonizing annual German Federal Statistical Office Accident Atlas releases beginning in 2016. Provides standardized geospatial traffic accident data suitable for longitudinal analysis. Useful for investigating geographical patterns, accident hotspots, and changes in traffic-related injury events across Germany."
    },
    {
      "title": "German Social Accident Insurance (DGUV): Occupational Accident Statistics, 2010–2025",
      "url_or_doi": "https://publikationen.dguv.de/statistiken/arbeitsunfallgeschehen/",
      "justification": "Official annual statistical reports on occupational accidents in Germany, with separate editions for every year from 2010 through 2025. Contains information on workplace accidents and their consequences, supporting analysis of occupational injury trends. Particularly relevant for research on injuries sustained at work. Data are published primarily in statistical PDF reports rather than as a single downloadable dataset."
    },
    {
      "title": "DGUV: Occupational Accident Statistics and Long-Term Trends",
      "url_or_doi": "https://publikationen.dguv.de/statistiken/arbeitsunfallgeschehen/",
      "justification": "The German Social Accident Insurance publication series provides longitudinal statistics on reportable and fatal occupational accidents. Historical editions allow comparisons across the 2010s and 2020s. Useful for identifying changes in workplace injury frequency and severity, although coverage is limited to accidents falling within the relevant statutory accident insurance system."
    },
    {
      "title": "German Federal Health Monitoring: Trauma and Injury Statistics",
      "url_or_doi": "https://www.gbe-bund.de/stichworte/TRAUMA.html",
      "justification": "The German Federal Health Monitoring system provides access to statistical sources concerning trauma and injuries, including hospital diagnoses, rehabilitation statistics, and inpatient diagnoses and procedures. Includes references to annual statistical series covering the 2010s and 2020s. Particularly useful for locating multiple official datasets on traumatic injuries and their treatment in Germany."
    },
    {
      "title": "Robert Koch Institute: Accident Injuries Among Adults in Germany (GEDA 2010)",
      "url_or_doi": "https://www.gbe-bund.de/pdf/unfallgeschehen_erwachsenen_d.pdf",
      "justification": "Official population-health survey analysis based on the German Health Update (GEDA) 2010. Contains statistical tables on injuries among adults, including open wounds, fractures, concussions, and dislocations. Provides breakdowns by age, sex, and sociodemographic characteristics. Particularly relevant for wound-specific research because open wounds are explicitly distinguished from other injury types. The linked resource is a statistical report rather than the underlying microdata."
    },
    {
      "title": "Eurostat: Historical Hospital Discharges by Diagnosis and Region, Males, 2000–2021",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/page/HLTH_CO_DISCH1M",
      "justification": "Eurostat dataset containing historical hospital discharge statistics by diagnosis and regional classification. Includes Germany and supports analysis of injury-related hospitalizations using diagnostic categories covering injuries, poisoning, and other consequences of external causes. Provides observations covering the 2010s and early 2020s, making it useful for comparing German injury patterns with those in other European countries. This particular table covers male patients."
    },
    {
      "title": "Eurostat: Hospital Discharges by Diagnosis",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/EN/hlth_hosd_esms.htm",
      "justification": "Official Eurostat hospital discharge statistics covering European countries, including Germany. Diagnostic categories include injuries, poisoning, and other consequences of external causes. The current statistical framework covers data from 2023 onward, while separate historical datasets provide earlier observations. Suitable for examining injury-related hospitalization rates and comparing Germany with other European countries. The link leads to the dataset metadata and access information."
    },
    {
      "title": "Eurostat: Hospital Discharges for Injuries, Poisoning, and Other External Causes",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/health/information-data",
      "justification": "Eurostat's official health data portal provides access to hospital discharge statistics classified by diagnosis, including injuries and poisoning. Researchers can filter relevant datasets for Germany and available years during the 2010s and 2020s. Useful for measuring hospital-treated injury burdens and conducting standardized international comparisons."
    },
    {
      "title": "Eurostat: European Health Interview Survey (EHIS), Including Germany",
      "url_or_doi": "https://www.gesis.org/en/gml/european-microdata/ehis",
      "justification": "The European Health Interview Survey provides harmonized population-health survey data for participating European countries, including Germany. Survey waves during the 2010s and 2020s support research on accidents and injuries, subject to wave-specific questionnaire content and data availability. Useful for studying self-reported accidents and demographic risk factors, complementing hospital statistics that capture primarily medically treated injuries."
    },
    {
      "title": "Destatis: Annual Road Traffic Accident Statistical Reports",
      "url_or_doi": "https://www.destatis.de/DE/Themen/Gesellschaft-Umwelt/Verkehrsunfaelle/_inhalt.html",
      "justification": "Official German Federal Statistical Office publication portal offering annual road traffic accident statistics, downloadable statistical tables, historical publications, and time-series reports. Includes information about injured road users, fatal accidents, and accident characteristics. Provides an extensive source for investigating road traffic injuries during the 2010s and 2020s, with greater detail than basic national injury counts."
    }
  ]
}
